look.customCSS:
/* ───── 魔镜 · 第一批 ───── */
/* 整页＝金框：底色是金，两边一排铆钉；镜面（body）缩进来，四角圆、内阴影 */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScxMicgaGVpZ2h0PScyMic+PGNpcmNsZSBjeD0nNicgY3k9JzExJyByPScxLjYnIGZpbGw9JyM1RTQ0MTQnIG9wYWNpdHk9Jy41NScvPjwvc3ZnPg==") 2px 0/12px 22px repeat-y,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScxMicgaGVpZ2h0PScyMic+PGNpcmNsZSBjeD0nNicgY3k9JzExJyByPScxLjYnIGZpbGw9JyM1RTQ0MTQnIG9wYWNpdHk9Jy41NScvPjwvc3ZnPg==") right 2px top 0/12px 22px repeat-y,linear-gradient(135deg,#F6E3A6 0%,#C9A04E 35%,#8F6A26 60%,#D9B866 80%,#A67C30 100%) !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}
[data-wk="body"]{position:relative !important;margin:0 12px !important;border-radius:14px !important;background:url("data:image/svg+xml;base64,") center top/100% auto no-repeat,radial-gradient(circle at 25% 28%,rgba(143,180,217,.28),transparent 45%),radial-gradient(circle at 85% 70%,rgba(110,143,181,.28),transparent 45%),linear-gradient(170deg,#3B4A5C,#1F2832 50%,#2D3948) !important;box-shadow:inset 0 0 0 1.2px #5E4414,inset 0 4px 14px rgba(0,0,0,.55) !important}

/* 顶栏：金框里嵌一块墨色面板，两道金细线；下面镜子顶上正中镶一颗红宝石 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:transparent !important;border-bottom:none !important;box-shadow:none !important;gap:6px !important;z-index:5 !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;left:10px !important;right:10px !important;top:calc(var(--app-safe-top, 0px) + 2px) !important;bottom:6px !important;border-radius:12px !important;background:#17110F !important;box-shadow:0 0 0 1.2px #5E4414,inset 0 0 0 3.5px #17110F,inset 0 0 0 4.1px rgba(201,160,78,.8) !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:50% !important;top:calc(100% - 4px) !important;width:28px !important;height:28px !important;margin-left:-14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 3px 3px rgba(0,0,0,.5)) !important;z-index:6 !important;pointer-events:none !important}
[data-wk="chathead"] + *:not([data-wk="body"]){margin:16px 12px 0 !important}
[data-wk="body"]{padding-top:26px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#F6EFE2 !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.08em !important;white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}
[data-wk="headname"] > [data-wk="headink"] > span{flex:none !important}
[data-wk="headname"] > [data-wk="headdim"]{font-size:0 !important;letter-spacing:0 !important;white-space:nowrap !important;line-height:1 !important;margin-top:3px !important}
[data-wk="headname"] > [data-wk="headdim"]::before{content:"Mirror, mirror" !important;font:italic 400 12.5px/1.2 Didot,"Bodoni MT","Playfair Display",Georgia,serif !important;letter-spacing:.03em !important;color:#C9A04E !important}
[data-wk="headdim"]{color:#A79C8C !important;white-space:nowrap !important;letter-spacing:.12em !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#F6EFE2 !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#F6EFE2 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:32px !important;min-width:32px !important;height:32px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-right:6px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：一圈金边，左上一道高光 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:50% !important;box-shadow:0 0 0 4px #C9A04E,0 0 0 5px #5E4414,0 4px 8px 3px rgba(0,0,0,.45) !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:50% !important}
button[data-wk="avatar"]::after,span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;inset:12% !important;border-radius:50% !important;border:1.4px solid transparent !important;border-top-color:rgba(255,255,255,.5) !important;border-left-color:rgba(255,255,255,.35) !important;transform:rotate(-15deg) !important;pointer-events:none !important}
[data-wk="chathead"] img[data-wk="avatar"],[data-wk="chathead"] [data-wk="avatar"]{box-shadow:0 0 0 3px #C9A04E !important}

/* 我的话：红丝绒牌，金边，里面再描一道细金线，底下压一层影 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:10px !important;letter-spacing:.06em !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#A51A2B,#6B0E1A) !important;color:#F6EFE2 !important;border:1.1px solid #C9A04E !important;box-shadow:inset 0 0 0 3px transparent,inset 0 0 0 3.5px rgba(201,160,78,.7),0 4px 0 rgba(0,0,0,.35),0 6px 10px rgba(0,0,0,.3) !important}
/* 他的话：镜面里浮出来的一块玻璃——半透明、亮白边、上沿一道高光、字带一点光晕；一串第一条右上角闪一大一小两颗星 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(180deg,rgba(255,255,255,.55),rgba(255,255,255,.55)) 12px 4px/45% 1.4px no-repeat,linear-gradient(135deg,rgba(255,255,255,.30),rgba(191,216,240,.12) 50%,rgba(255,255,255,.22)) !important;color:#fff !important;border:1.2px solid rgba(255,255,255,.7) !important;box-shadow:0 0 16px rgba(207,230,255,.18) !important;text-shadow:0 0 6px rgba(221,235,255,.7) !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;right:-14px !important;top:-12px !important;width:24px !important;height:24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important;left:auto !important;bottom:auto !important;animation:mmTwinkle 2.8s ease-in-out infinite !important}
@keyframes mmTwinkle{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.5;transform:scale(.8)}}

/* 时间：两道细白线中间夹时间，两边各一颗小星；底下一行「魔镜醒着」 */
[data-wk="time"]{display:flex !important;justify-content:center !important}
[data-wk="time"] > span{display:block !important;text-align:center !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC05IDEyIDE4Jz48cGF0aCBkPSdNMCAtNy41IFEwLjYgLTAuNiA1IDAgUTAuNiAwLjYgMCA3LjUgUS0wLjYgMC42IC01IDAgUS0wLjYgLTAuNiAwIC03LjVaJyBmaWxsPScjZmZmJyBvcGFjaXR5PScwLjknLz48L3N2Zz4=") left 4px top 6px/7px 10px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC05IDEyIDE4Jz48cGF0aCBkPSdNMCAtNy41IFEwLjYgLTAuNiA1IDAgUTAuNiAwLjYgMCA3LjUgUS0wLjYgMC42IC01IDAgUS0wLjYgLTAuNiAwIC03LjVaJyBmaWxsPScjZmZmJyBvcGFjaXR5PScwLjknLz48L3N2Zz4=") right 4px top 6px/7px 10px no-repeat !important;border:none !important;box-shadow:none !important;color:#EAF2FB !important;font-family:Didot,"Bodoni MT","Playfair Display",Georgia,serif !important;letter-spacing:.25em !important;font-size:11.5px !important;padding:2px 18px !important;position:relative !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;position:absolute !important;top:10px !important;width:56px !important;height:1px !important;background:rgba(255,255,255,.5) !important}
[data-wk="time"] > span::before{right:100% !important}
[data-wk="time"] > span::after{left:100% !important}
[data-wk="time"]::after{content:"魔镜醒着" !important;position:absolute !important;left:0 !important;right:0 !important;margin-top:24px !important;text-align:center !important;font-size:9.5px !important;letter-spacing:.4em !important;color:#AAB6C2 !important}
[data-wk="time"]{position:relative !important;padding-bottom:16px !important}

/* 已送达＝后面一个小空心圈；已读＝前面一颗星，字写「镜已阅」 */
[data-wk="meta"]{color:#AAB6C2 !important;font-size:10px !important;letter-spacing:.15em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"][data-read="0"]::after{content:"" !important;width:10px !important;height:10px !important;flex:none !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PGNpcmNsZSBjeD0nNicgY3k9JzYnIHI9JzMnIGZpbGw9J25vbmUnIHN0cm9rZT0nI0FBQjZDMicgc3Ryb2tlLXdpZHRoPScxLjInLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]{font-size:0 !important}
[data-wk="meta"][data-read="1"] *{display:none !important}
[data-wk="meta"][data-read="1"]::before{content:"镜已阅" !important;font-size:10px !important;letter-spacing:.15em !important;padding-left:14px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC05IDEyIDE4Jz48cGF0aCBkPSdNMCAtNy41IFEwLjYgLTAuNiA1IDAgUTAuNiAwLjYgMCA3LjUgUS0wLjYgMC42IC01IDAgUS0wLjYgLTAuNiAwIC03LjVaJyBmaWxsPScjZmZmJyBvcGFjaXR5PScwLjk1Jy8+PC9zdmc+") left center/7px 10px no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:linear-gradient(135deg,rgba(255,255,255,.3),rgba(191,216,240,.12)) !important;border:1.2px solid rgba(255,255,255,.7) !important;border-radius:10px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#fff !important;box-shadow:0 0 4px #fff !important}
[data-wk="name"]{color:#AAB6C2 !important}

/* 动描：镜面上一段像雾气写出来的字——没有框，白字带光晕，上下两颗小星 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{position:relative !important;display:block !important;background:radial-gradient(ellipse at 50% 50%,rgba(207,230,255,.10),transparent 70%) !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#DDEBFF !important;font-style:italic !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.12em !important;text-align:center !important;text-shadow:0 0 8px rgba(207,230,255,.6) !important;padding:16px 26px !important}
[data-wk="narrink"]::before,[data-wk="narrink"]::after{content:"" !important;position:absolute !important;left:50% !important;width:8px !important;height:12px !important;margin-left:-4px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC05IDEyIDE4Jz48cGF0aCBkPSdNMCAtNy41IFEwLjYgLTAuNiA1IDAgUTAuNiAwLjYgMCA3LjUgUS0wLjYgMC42IC01IDAgUS0wLjYgLTAuNiAwIC03LjVaJyBmaWxsPScjZmZmJyBvcGFjaXR5PScwLjg1Jy8+PC9zdmc+") center/contain no-repeat !important}
[data-wk="narrink"]::before{top:0 !important}
[data-wk="narrink"]::after{bottom:0 !important}
/* 系统提示：一行小灰字，前面一颗星 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#AAB6C2 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.12em !important;padding-left:14px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC05IDEyIDE4Jz48cGF0aCBkPSdNMCAtNy41IFEwLjYgLTAuNiA1IDAgUTAuNiAwLjYgMCA3LjUgUS0wLjYgMC42IC01IDAgUS0wLjYgLTAuNiAwIC03LjVaJyBmaWxsPScjZmZmJyBvcGFjaXR5PScwLjgnLz48L3N2Zz4=") left center/7px 10px no-repeat !important}
[data-wk="sysnoteclose"]{color:#AAB6C2 !important}
/* 深底上的灰字提亮：日程条、线下文风那行 */
[data-wk="chathead"] + *:not([data-wk="body"]),[data-wk="chathead"] + *:not([data-wk="body"]) *{color:#F6EFE2 !important}

/* 底栏：金框里嵌一块墨色面板；输入框是一块玻璃；加号、回复是金圈，最右是红宝石的「让他回复」，发送是左边的金圈 */
[data-wk="composer"]{position:relative !important;overflow:visible !important;background:transparent !important;border-top:none !important;box-shadow:none !important;align-items:center !important;gap:10px !important;padding-left:22px !important;padding-right:22px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:10px !important;right:10px !important;top:6px !important;bottom:6px !important;border-radius:12px !important;background:#17110F !important;box-shadow:0 0 0 1.2px #5E4414,inset 0 0 0 3.5px #17110F,inset 0 0 0 4.1px rgba(201,160,78,.8) !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="chatinput"]{background:linear-gradient(135deg,rgba(255,255,255,.18),rgba(191,216,240,.08) 50%,rgba(255,255,255,.14)) !important;border:1px solid rgba(255,255,255,.6) !important;border-radius:10px !important;color:#fff !important;letter-spacing:.1em !important}
[data-wk="chatinput"]::placeholder{color:#C9D6E4 !important}
[data-wk="chatplus"],[data-wk="chatreply"],[data-wk="send"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatreply"]{width:46px !important;min-width:46px !important;height:46px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important;filter:drop-shadow(0 3px 4px rgba(0,0,0,.5)) !important}
[data-wk="chatplus"] *,[data-wk="chatreply"] *,[data-wk="send"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="chatreply"]:active,[data-wk="send"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:#17110F !important;border-top:1px solid #C9A04E !important}
